// 一次ソース: 東京都教育委員会公式ページ
// (`www.kyoiku.metro.tokyo.lg.jp/information/press/2025/09/2025092502`)から
// リンクされるPDF(`www.kyoiku.metro.tokyo.lg.jp/documents/d/kyoiku/20250925_n2_10`・
// 「普通教育を主とする学科」・全7頁)。テキスト埋め込み型PDFだが列が極めて密な
// マトリクス表のため、pdftotext -layoutの結果だけでは列の対応関係が確定できず、
// pdftoppm(200dpi)で頁1を画像化しPythonでcrop()して拡大確認してから転記した
// ([[fable5-loop-protocol]]の密なマトリクス表の罠を踏まえた対応)。
//
// 全7頁のうち頁1-7(普通教育を主とする学科・頁1=日比谷/三田/戸山/竹早/向丘/上野/日本橋/本所/城東/東/深川/大崎/小山台の13校・頁2=八潮/駒場/目黒/大森/田園調布/雪谷/桜町/千歳丘/松原/青山/広尾/鷺宮/武蔵丘の13校・頁3=杉並/豊多摩/西/豊島/文京/竹台/板橋/大山/北園/高島/井草/石神井/田柄/練馬の14校・頁4=光丘/青井/足立/足立新田/足立西/江北/淵江/葛飾野/南葛飾/江戸川/葛西南/小岩/小松川/篠崎/紅葉川/片倉の16校・頁5=八王子北/八王子東/富士森/松が谷/立川/武蔵野北/多摩/府中/府中西/府中東/昭和/拝島/神代/調布北/調布南の15校・頁6=小川/成瀬/野津田/町田/山崎/小金井北/小平/小平西/小平南/日野/日野台/南平/東村山西/国立/福生/狛江の16校・頁7=東大和/東大和南/清瀬/久留米西/武蔵村山/永山/羽村/五日市/田無/保谷の10校+島しょ6校[大島/新島/神津/三宅/八丈/小笠原・推薦は「実施しない」で第一次・第二次のみ]計16校)303
